What is logged?
```typescript
const chain: Middleware[] = [
  (c, n) => { c.log.push("a"); n(); c.log.push("a2"); },
  (c, n) => { c.log.push("b"); n(); },
];
const ctx = { log: [] as string[] };
const run = (i: number): void => { const mw = chain[i]; if (mw) mw(ctx, () => run(i + 1)); };
run(0);
console.log(ctx.log.join(","));
```

