challenges.solution:
type Result<T, E> =
  | { ok: true; value: T }
  | { ok: false; error: E };

function safeDivide(a: number, b: number): Result<number, string> {
  if (b === 0) return { ok: false, error: "divide by zero" };
  return { ok: true, value: a / b };
}

console.log(JSON.stringify(safeDivide(10, 4)), JSON.stringify(safeDivide(1, 0)));

