challenges.solution:
function groupBy<T, K extends string>(items: T[], key: (t: T) => K): Record<K, T[]> {
  const out = {} as Record<K, T[]>;
  for (const item of items) {
    const k = key(item);
    (out[k] ??= []).push(item);
  }
  return out;
}

console.log(JSON.stringify(groupBy(["apple", "avocado", "banana", "blueberry", "cherry"], (s) => s[0] as string)));
